mapper.select:
SELECT l.ledger_id, l.emp_id, l.att_month, l.month_work_days, l.att_days, l.leave_days, l.overtime_days, l.absent_days, l.ledger_status, l.create_time, l.update_time, COALESCE(e.emp_code, '') AS emp_code, COALESCE(e.emp_name, '') AS emp_name, e.dept_id AS dept_id, COALESCE(d.dept_name, '') AS dept_name FROM hr_att_ledger l LEFT JOIN sys_emp e ON l.emp_id = e.emp_id LEFT JOIN sys_dept d ON e.dept_id = d.dept_id WHERE 1=1
AND l.emp_id = #{empId}
AND l.att_month = #{attMonth}
AND l.ledger_status = #{ledgerStatus}
AND e.emp_code = #{empCode}
AND e.emp_name LIKE CONCAT('%', #{empName}, '%')
AND e.dept_id = #{deptId}
ORDER BY l.att_month DESC, l.create_time DESC

mapper.update:
UPDATE hr_att_ledger
month_work_days = #{monthWorkDays}, att_days = #{attDays}, leave_days = #{leaveDays}, overtime_days = #{overtimeDays}, absent_days = #{absentDays}, ledger_status = #{ledgerStatus},
WHERE ledger_id = #{ledgerId}
